{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C55"],
      "claim": "Methocarbamol, which shares the guaiacol glyceryl ether substructure with the query, has 90% oral bioavailability in humans, directly supporting a high F prediction.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C40"],
      "claim": "Lidocaine, which shares the 2,6-dimethylphenyl amide motif, has oral bioavailability values around 35-42% in humans, above the 20% threshold, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C47"],
      "claim": "Tocainide, a close 2,6-dimethylphenyl amide analogue, is virtually completely bioavailable after oral dosing, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C41"],
      "claim": "Recainam, containing the 2,6-dimethylphenyl amide/urea and basic amine features, has absolute oral bioavailability of 73% in healthy men, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C49"],
      "claim": "Propranolol, sharing the aryloxypropanolamine scaffold, has mean oral bioavailability around 19-25% with some values below 20%, indicating possible first-pass liability; this is the main contradictory evidence but is outweighed by closer amide-containing analogues.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query combines a guaiacol glyceryl ether (methocarbamol-like) and a 2,6-dimethylphenyl amide (lidocaine/tocainide-like) linked through a piperazine. The closest analogue, methocarbamol, is 90% bioavailable; the 2,6-dimethylanilide class is generally well absorbed with F mostly ≥35%, and aryloxypropanolamine beta-blockers such as oxprenolol and bevantolol have F 24-98%. Although propranolol shows borderline first-pass metabolism, the preponderance of transferable experimental evidence supports F ≥20%. The physicochemical prior is mixed but not disqualifying.",
  "evidence_gaps": [
    "No experimental oral bioavailability data exist for the exact piperazine-acylanilide query molecule.",
    "Potential piperazine metabolism or efflux liability is not directly measured in the available analogues.",
    "Propranolol-like first-pass metabolism cannot be fully excluded from structure alone."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

